  en: { roleBoundary: "Fixed boundary: cannot override · append only · permissions can only narrow.", globalUserWarning: "Untrusted user context; never system text.", systemWarning: "Trusted system extension: append only; cannot override boundaries.", secretConfigured: "{count} secret(s) configured", system: "system", user: "user", trusted: "trusted", untrusted: "untrusted" },
